from pathlib import Path
import json,csv,html,collections,hashlib
D=Path(__file__).parent;Q=D/'audit';read=lambda p:json.loads((Q/p).read_text(encoding='utf8'));E=lambda x:html.escape(str(x));num=lambda x:f'{x:,.6f}'
cases=read('scenarios.json')['scenarios'];opt=read('optimization.json');base=cases[0]['result'];scores={r['id']:r['score'] for r in base['rows']}
suites=[]
for fn,label in [('engine-qa.json','Scenario engine'),('oracle-qa.json','Independent source workbook replay'),('browser-qa.json','Six-tab browser and extract'),('regression-browser-qa.json','Browser regression and recovery'),('refresh-ui-qa.json','Changed-source refresh'),('exco-qa.json','ExCo workflow and configuration controls'),('export-qa.json','Excel exports'),('compatibility-qa.json','v5.7 calculation parity and import boundaries'),('final-view-qa.json','Final comparison and report rendering')]:
 if (Q/fn).exists():
  raw=read(fn);checks=raw['checks'];passed=sum(x.get('passed',x.get('status')=='PASS') for x in checks);suites.append((label,len(checks),passed,fn,raw.get('fatal')))
total=sum(x[1] for x in suites);passed=sum(x[2] for x in suites)
style='''body{font:16px Calibri,Arial,sans-serif;color:#16365c;margin:0;background:#f5f8fc}header{background:#0B5ED7;color:white;padding:32px 5%}main{max-width:1400px;margin:25px auto;padding:0 30px}section{background:white;padding:24px;margin:20px 0;border:1px solid #d5deeb;border-radius:8px}h1{font-size:30px}h2{color:#00126e}p,li{line-height:1.55}table{border-collapse:collapse;width:100%;font-size:14px}th{background:#eaf2ff;text-align:left;position:sticky;top:0}td,th{padding:10px;border-bottom:1px solid #dae2ee;vertical-align:top}.scroll{overflow:auto}.kpis{display:flex;gap:20px;flex-wrap:wrap}.kpis article{flex:1;min-width:160px;background:#edf4ff;padding:20px}.kpis b{display:block;font-size:28px;color:#00126e}code{overflow-wrap:anywhere}a{color:#075bd8}details{margin:15px 0}summary{cursor:pointer;font-weight:bold}small{font-size:13px}svg{max-width:100%;height:auto}@media print{header{background:white;color:black}section{break-inside:avoid}th{position:static}main{padding:0}.scroll{overflow:visible}}'''
def table(head,rows):return '<div class="scroll"><table><thead><tr>'+''.join('<th>'+E(h)+'</th>' for h in head)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+str(v)+'</td>' for v in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def page(title,body):return '<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+title+'</title><style>'+style+'</style><header><p>AOP 2027 · v5.8.0 · 30 September 2026</p><h1>'+title+'</h1></header><main>'+body+'</main></html>'
requirements=[
('EXCO58-01','Default leadership view','Open the new build in ExCo view. Keep all six original tabs accessible through Six-tab workbench.'),
('EXCO58-02','Single calculation result','Company KPIs, priority bars, receiving organisation costs, drilldowns and exports use the same scenario result and finance ledger.'),
('EXCO58-03','Scope clarity','Company position always shows company cost. The 16-leader filter applies to accountable Programs in My portfolio and Decisions. Receiving-BU allocation is separate from accountability.'),
('EXCO58-04','Benefit meaning','Show funded hard and soft submitted lifetime benefit claims separately. Do not label claims as annual savings or realised returns.'),
('EXCO58-05','Recommendation boundary','Compare baseline, best tested option and current scenario. State objective, protected funding and grid size. Invalidate the recommendation when the Programs source hash changes.'),
('EXCO58-06','Recommended draft','Save the current scenario before creating a fresh recommended child draft. Preserve parent lineage. Apply source settings without copying current manual decisions.'),
('EXCO58-07','Decision preview','For P4 and optional P5, preview partial scope or exclusion with a rationale and exact before/after funding, total IT and budget excess. Cancel leaves state unchanged.'),
('EXCO58-08','Stale preview guard','Apply only when scenario ID, revision and source hash still match the preview. Otherwise require a new preview.'),
('EXCO58-09','Trade-off isolation','Apply whole-Programs trade-offs to the selected leader and F&R or BU Led stream. Keep the base budget unchanged and disclose any target undershoot.'),
('EXCO58-10','Lifecycle and evidence','Save, undo, finalise, fork and full Excel export use existing commands. Finalised scenarios disable editing. Changed-source unresolved decisions continue to block finalisation.'),
('EXCO58-11','Portable input validation','Reject imported negative or non-numeric requested amounts, merit outside 0–100, merit without rationale, and invalid review objects.'),
('EXCO58-12','Release preservation','Create v5.8.0 without changing the v5.7.0 HTML or either source workbook. Run 32 scenarios, source replay, exports, browser regression, refresh and ExCo tests.')]
(D/'requirements.json').write_text(json.dumps(requirements,indent=2,ensure_ascii=False),encoding='utf8')
trace=[];matrix=[]
for c in cases:
 r=c['result'];s=c['settings'];f=r['finance'];canonical=sum(x['final']*scores[x['id']]/100 for x in r['rows'] if not x.get('isPmi',False));wm=canonical/r['totals']['allocation']*100 if r['totals']['allocation'] else 0
 settings=f"Budget {s['budget']}; tolerance {s['tolerance']}%; floor {s['merit']}; weights {s['weights']}; "+'; '.join(k+': '+str(s[k]) for k in ['lfr','sustain','value','itsimp'])+f"; P5 {s['itsimpMode']}; overrides {len(c['overrides'])}; reviews {len(c['reviews'])}"
 matrix.append([E(c['id']),E(c['name']),num(r['totals']['allocation']),num(r['streams']['ew']['allocation']),num(r['streams']['bu']['allocation']),num(f['totals']['total']),num(r['totals']['over']),f'{wm:.3f}',f'<details><summary>Settings</summary>{E(settings)}</details>'])
 for x in r['rows']:
  trace.append({'Scenario':c['id'],'Name':c['name'],'Programs ID':x['id'],'Programs':x['name'],'Sheet':x['sourceSheet'],'Row':x['sourceRow'],'Source SHA256':opt['sourceHash'],'Accountable ExCo':x['exco'],'Organisation':x['org'],'Stream':x['stream'],'Source request M€':x['sourceCost'],'Scenario request M€':x['cost'],'Source merit':scores[x['id']],'Scenario merit':x['score'],'Stage':x['stageName'],'Automatic M€':x['automatic'],'Funded M€':x['final'],'Unfunded M€':x['unfunded'],'Reason':x['reason']})
with (D/'32-scenarios-Programs-trace.csv').open('w',encoding='utf-8-sig',newline='') as w:
 writer=csv.DictWriter(w,fieldnames=list(trace[0]));writer.writeheader();writer.writerows(trace)
grid=[]
for g in opt['grid']:grid.append({k:g[k] for k in ['id','feasible','funded','count','canonicalUtility','weightedMerit','LFR','carry','sustain','value','itsimp','unallocated','totalIT']}|{'settings':json.dumps(g['settings'])})
with (D/'135-options-ranking.csv').open('w',encoding='utf-8-sig',newline='') as w:
 writer=csv.DictWriter(w,fieldnames=list(grid[0]));writer.writeheader();writer.writerows(sorted(grid,key=lambda g:-g['canonicalUtility']))
body=f'''<section><h2>Recommendation and validation outcome</h2><p>Retain the default €100M Optimal scenario for the ExCo decision baseline. It is the best of 135 tested lever combinations under the stated balanced objective. The new v5.8.0 build adds an ExCo decision view above the six-tab workbench. Funding, merit and finance outputs match v5.7.0 across all 32 scenarios; the v5.7.0 file remains unchanged.</p><div class="kpis"><article><b>{passed}/{total}</b>automated assertions passed</article><article><b>32</b>end-to-end scenarios</article><article><b>69,280</b>independent record field comparisons</article><article><b>135</b>recommendation candidates</article></div><p>Test outcome score: {passed/total*100 if total else 0:.1f}% of recorded assertions. This measures the tested implementation, not business certainty. Recommendation funding-weighted source merit: 60.088/100. It is a ranking measure, not a return forecast.</p><p><a href="AOP2027-IT-Portfolio-Scenario-Modelling-v5.8.0.html">Open v5.8.0</a> · <a href="ExCo-architecture-v5.8.0.html">ExCo architecture and requirements</a> · <a href="32-scenarios-Programs-trace.csv">13,856 Programs scenario records</a> · <a href="135-options-ranking.csv">All candidate settings and scores</a></p></section>'''
body+='''<section><h2>Recommended funding and decision logic</h2><p>Use a €100M base envelope, zero tolerance, default merit floor 45 and source score weights 40/25/15/10/10. LFR uses 82.384824% of its bucket to fund the verified €43.776M. Confirmed carry-over uses the approved baseline cap, with no ROI threshold. Sustain uses 60% of its bucket; Value receives the remaining envelope. IT Simplification is inactive as a separate fifth lever.</p>'''
body+=table(['Funding component','Exact M€'],[['Legal and Compliance',num(43.776)],['Confirmed carry-over',num(16.773)],['Sustain Engineering and Hygiene',num(20.609)],['Value Based Portfolio',num(18.805)],['Base Programs / 162 funded',num(99.963)],['Unspent base budget',num(.037)],['PMI on top / 4 Programs',num(5.19)],['Operations',num(470.3144630385122)],['Total IT',num(575.4674630385123)]])
body+='''<p>The search maximises Σ(funded amount × unchanged source merit ÷ 100). It protects every baseline-funded LFR and confirmed carry-over amount and requires at least €20.609M Sustain. Search grid: LFR 82.384824%, 90%, 100%; Sustain 60–100% in 5-point steps; IT Simplification reserve €0/2/5/8/10M; Value at 100% bucket, subject to residual budget. All 135 candidates were feasible. The winning allocation is identical to baseline; no Programs move.</p><p>This is a finite lever search, not a global optimisation of project combinations. Source dependency text, delivery capacity, timing, benefit overlap and realised cash flows are not quantified in the objective. A different continuity preference can produce a different recommendation.</p></section>'''
body+='<section><h2>Receiving organisation allocation</h2><p>Exact values below include Operations own consumption, Regions and Functions once. The €40M BU row 276 line is a charging key only. Its percentages determine EW allocations; the €40M is excluded from demand.</p>'+table(['Recipient','BU Programs','EW charge','Operations own','Regions','Functions','PMI','Total M€'],[[E(r['recipient'])]+[num(v) for v in [r['single']+r['cross']+r['indirect']+r['other'],r['ew'],r['own'],r['region'],r['functions'],r['pmi'],r['total']]] for r in base['finance']['rows']])+'</section>'
body+='''<section><h2>Key findings and remaining gaps</h2><ol><li><b>EW residual is intentional.</b> Preserve 22.6303317536% unallocated, equal to €11.250895735M in Optimal. This is the approved allocation treatment, not a failed reconciliation.</li><li><b>Other BU residual is €1.822M.</b> It includes €1.357M explicit indirect unallocated cost and €0.465M from Bu-06 without a recipient percentage. These remain visible; the model does not invent a recipient split.</li><li><b>Funding choice remains material.</b> €180.0599M of base requested demand is unfunded. This is not all eligible backlog: confirmed carry-over caps, source decisions, merit and whole-Programs fitting affect it. LFR bucket demand is €53.136M; €43.776M verified funding leaves €9.36M outside the default allocation.</li><li><b>More budget alone does not solve coverage.</b> The €350M stress scenario funds €149.604M base under the retained rules. The zero-budget test still has €475.504463M total IT from Operations plus separately funded PMI.</li><li><b>Manual and tolerance excess is explicit.</b> Scenario 07 funds €100.413M after manual decisions. A 5% tolerance funds €104.990M automatically. Neither should be described as a strict €100M outcome.</li><li><b>Merit sensitivity is uneven.</b> Floors 0 and 65 produce the same baseline funding; floor 100 reduces it to €81.158M. Increasing the payback weight funds €86.298M. These are policy sensitivities, not calculation defects.</li><li><b>Benefit claims remain accepted for prioritisation.</b> Optimal funded base Programs carry €5,153.663M hard and €7,574.797M soft submitted lifetime claims, kept separate. One hard claim represents 24.25% of funded hard claims. Validation of input does not establish additive or realised cash benefit.</li><li><b>Source exclusions remain auditable.</b> Nine missing-request and four uninterpretable-decision rows are excluded from active demand and retained in the source audit. There are 433 active Programs including PMI. No new source refresh was inferred; both supplied workbook hashes match the v5.7.0 build.</li><li><b>Offline meeting workflow has limits.</b> Finalised is a local scenario lock, not an electronic approval or centrally authenticated sign-off. Save and export decision evidence for recovery. Browser checks cover desktop Chrome at 1366–1920px; mobile, other browsers, concurrent multi-user editing and Excel recalculation in the desktop application are outside this suite.</li><li><b>Import guard strengthened in v5.8.0.</b> Imported request and merit reviews now enforce the same amount/range/rationale boundaries as live edits. This does not change valid scenario calculation results.</li></ol></section>'''
body+='<section><h2>All 32 scenarios</h2><p>Each scenario traversed all six tabs, the ExCo finance view, the Excel export and independent source replay. M€ values are exact to six displayed decimals here. The source workbooks were read directly by an independent Python implementation for request, stage, score, automatic/final funding, recipient totals and Operations components. Export tests inspect actual downloaded XLSX files with a separate parser.</p>'+table(['ID','Scenario','Base M€','F&R M€','BU M€','Total IT M€','Over base M€','Source merit /100','Configuration'],matrix)+'</section>'
body+='<section><h2>Validation suites and reproducibility</h2>'+table(['Suite','Passed','Assertions','Evidence'],[[E(a),c,b,f'<a href="audit/{E(d)}">{E(d)}</a>'+(' FATAL '+E(e) if e else '')] for a,b,c,d,e in suites])+'<p>Configuration coverage includes four presets; zero, 80, 95, 100, 120 and 350M budgets; 0/2/5% tolerance; all four editable levers and all three bases; optional fifth lever on/off; five score weights; merit floor boundaries; EW/BU requested and merit reviews; inclusion/exclusion/partial scope; leader trade-offs; save/reload; portable restore/checksum rejection; finalise/fork/undo; refresh holds; 22 extract datasets and 649 column filters.</p><p>Independent field replay covers 433 × 32 × 5 = 69,280 comparisons, not an additional set of assertion counts. Browser and export tests cover the same cases through distinct surfaces. Fixed-delay portable test timing was replaced by completion-event waits after the first concurrent run; final results reflect the corrected harness.</p></section>'
prov=read('build-provenance.json');body+='<section><h2>Source and baseline integrity</h2>'+table(['File','SHA256'],[[E(Path(prov['baselineFile']).name),'<code>'+prov['baselineSha256']+'</code>'],['Programs workbook','<code>'+opt['sourceHash']+'</code>'],['Operations workbook','<code>176a6192da3356bcedd9f2babc8318c45977e7658d03172f9e2cb643d22e4668</code>']])+'<p>The release receipt records final destination hashes. All v5.8.0 release files are new. The original v5.7.0 HTML and source spreadsheets are preserved.</p></section>'
(D/'ExCo-QA-report-v5.8.0.html').write_text(page('ExCo build validation and recommendation',body),encoding='utf8')
arch='''<section><h2>One scenario with two working views</h2><p>ExCo opens a concise company decision view. Portfolio analysts retain all six tabs for detailed configuration, Programs review and Operations analysis. Both views operate on the same current scenario and shared finance result. No separate executive calculation model is introduced.</p><svg viewBox="0 0 1100 310" role="img" aria-label="Source workbooks feed one scenario engine and ledger, used by ExCo, six tabs and exports"><defs><marker id="a" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0 0 L8 4 L0 8" fill="#075bd8"/></marker></defs><g fill="#edf4ff" stroke="#0b5ed7"><rect x="15" y="90" width="235" height="125" rx="8"/><rect x="340" y="90" width="300" height="125" rx="8"/><rect x="735" y="15" width="340" height="75" rx="8"/><rect x="735" y="120" width="340" height="75" rx="8"/><rect x="735" y="225" width="340" height="75" rx="8"/></g><g fill="#00126e" font-family="Calibri,Arial" font-size="20" text-anchor="middle"><text x="132" y="135">Programs + Operations</text><text x="132" y="170">Original source snapshots</text><text x="490" y="133">Scenario engine</text><text x="490" y="169">One receiving-cost ledger</text><text x="905" y="60">ExCo decision view</text><text x="905" y="165">Six-tab workbench</text><text x="905" y="270">Excel evidence + scenario recovery</text></g><g fill="none" stroke="#075bd8" stroke-width="3" marker-end="url(#a)"><path d="M250 152 H332"/><path d="M640 152 H690 V52 H727"/><path d="M640 152 H727"/><path d="M640 152 H690 V262 H727"/></g></svg></section><section><h2>Meeting journey</h2><ol><li><b>Company position.</b> Read five KPIs, funded priority amounts and receiving organisation costs. Total IT includes base Programs, PMI and Operations; unallocated is already included.</li><li><b>My portfolio.</b> Select one of 16 accountable leaders, review funded and deferred Programs and open source IDs. This ownership view does not redistribute receiving-BU costs.</li><li><b>Compare options.</b> Compare the approved baseline, best tested lever configuration and current scenario. Save the current scenario before creating the recommended draft.</li><li><b>Decisions.</b> Preview a leader/stream trade-off or a discretionary Programs funding amount with rationale. Inspect exact financial changes, then apply or cancel. Save, export and finalise the meeting scenario.</li></ol></section><section><h2>State and transaction boundaries</h2><p>The ExCo extension reads AOPApp.getState() and routes changes through the existing transaction, trade-off, save, export and undo functions. The original render publishes a change event; the ExCo view re-renders from the shared state. Recommendation analysis is embedded with the Programs source hash.</p><p>Preview uses a proposed copy. Apply compares scenario ID, revision and source hash against the preview, preventing stale decisions after an intervening edit. A finalised scenario blocks edit commands; a new working version retains parent lineage. The local version storage namespace is separate from v5.7.0.</p><p>Programs values and scenarios drive recipient fractions. Operations uses its fixed source allocation. EW uses the approved corrected BU row 276 percentages, leaving the residual visible. PMI is separate on top. Source references, source request and source merit remain distinct from scenario edits.</p></section><section><h2>Requirements and acceptance contract</h2>'''
arch+=table(['Requirement','Capability','Acceptance'],[[a,b,E(c)] for a,b,c in requirements])+'</section><section><h2>Release scope and future decisions</h2><p>The architecture is implemented in the new standalone v5.8.0 HTML. This release retains offline scenario ownership, local persistence and source-linked exports. Central approval authority, multi-user collaboration, delivery capacity constraints and dependency-aware optimisation would require additional requirements and source inputs; they are not implied by this build.</p><p><a href="ExCo-QA-report-v5.8.0.html">Read validation and gaps</a> · <a href="AOP2027-IT-Portfolio-Scenario-Modelling-v5.8.0.html">Open ExCo build</a></p></section>'
(D/'ExCo-architecture-v5.8.0.html').write_text(page('ExCo decision view architecture',arch),encoding='utf8')
(Q/'validation-summary.json').write_text(json.dumps({'version':'5.8.0','scenarios':32,'candidateOptions':135,'assertions':total,'passed':passed,'fieldComparisons':69280,'suites':suites,'recommendedBase':99.963,'recommendedTotalIT':575.4674630385123,'fundingWeightedSourceMerit':60.088012564648935},indent=2),encoding='utf8')
